# Diagnose chosen candidates by recreating candidate sets with same logic
from collections import Counter
h,w=len(g),len(g[0]); bg=3
for color in sorted(set(v for row in g for v in row if v!=bg)):
 pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==color]; ys=sorted({r for r,c in pts}); xs=sorted({c for r,c in pts}); cand=[]
 for r1 in ys:
  for r2 in ys:
   if r2<r1: continue
   for c1 in xs:
    for c2 in xs:
     if c2<c1: continue
     area=(r2-r1+1)*(c2-c1+1)
     if area<6: continue
     n=sum(g[r][c]==color for r in range(r1,r2+1) for c in range(c1,c2+1))
     if n/area>=.8: cand.append((n/area,n,area,r1,r2,c1,c2))
 cand.sort(key=lambda x:(x[0],x[1],x[2]),reverse=True); used=set(); chosen=[]
 for x in cand:
  _,n,a,r1,r2,c1,c2=x; cells={(r,c) for r in range(r1,r2+1) for c in range(c1,c2+1)}
  if cells&used: continue
  used|=cells; chosen.append(x)
 print(color,chosen[:15])
